//! One-time enrollment token generated by the hub UI.
//!
//! Format: `upr_enr.<id>.<secret>.<hub_fingerprint_hex>`. The fingerprint
//! pins the hub identity so the agent can authenticate the hub on first
//! contact. Only `<id>.<secret>` (see [`EnrollmentToken::auth_string`]) is sent
//! to the hub, and only inside the encrypted session.

use std::fmt;

use uuid::Uuid;

use crate::handshake::Fingerprint;

const PREFIX: &str = "upr_enr";

#[derive(Clone, PartialEq, Eq)]
pub struct EnrollmentToken {
    pub id: Uuid,
    pub secret: String,
    pub hub_fingerprint: Fingerprint,
}

impl fmt::Debug for EnrollmentToken {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "EnrollmentToken({}, <redacted>)", self.id)
    }
}

fn is_token_chars(s: &str) -> bool {
    !s.is_empty()
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_')
}

impl EnrollmentToken {
    pub fn encode(&self) -> String {
        format!(
            "{PREFIX}.{}.{}.{}",
            self.id,
            self.secret,
            hex_encode(&self.hub_fingerprint)
        )
    }

    pub fn parse(token: &str) -> Option<Self> {
        let mut parts = token.split('.');
        if parts.next()? != PREFIX {
            return None;
        }
        let id = Uuid::parse_str(parts.next()?).ok()?;
        let secret = parts.next()?;
        let fingerprint = hex_decode_32(parts.next()?)?;
        if parts.next().is_some() || !is_token_chars(secret) {
            return None;
        }
        Some(Self {
            id,
            secret: secret.to_owned(),
            hub_fingerprint: fingerprint,
        })
    }

    /// The part sent to the hub inside the encrypted session.
    pub fn auth_string(&self) -> String {
        format!("{}.{}", self.id, self.secret)
    }
}

/// Parses the `<id>.<secret>` form received by the hub.
pub fn parse_auth_string(s: &str) -> Option<(Uuid, String)> {
    let (id, secret) = s.split_once('.')?;
    if !is_token_chars(secret) {
        return None;
    }
    Some((Uuid::parse_str(id).ok()?, secret.to_owned()))
}

fn hex_encode(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn hex_decode_32(s: &str) -> Option<[u8; 32]> {
    if s.len() != 64 || !s.is_ascii() {
        return None;
    }
    let mut out = [0u8; 32];
    for (i, byte) in out.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).ok()?;
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn token() -> EnrollmentToken {
        EnrollmentToken {
            id: Uuid::now_v7(),
            secret: "abcDEF123-_".into(),
            hub_fingerprint: [0xab; 32],
        }
    }

    #[test]
    fn roundtrip() {
        let t = token();
        assert_eq!(EnrollmentToken::parse(&t.encode()), Some(t));
    }

    #[test]
    fn auth_string_roundtrip_carries_no_fingerprint() {
        let t = token();
        let s = t.auth_string();
        assert!(!s.contains("abab"));
        assert_eq!(parse_auth_string(&s), Some((t.id, t.secret)));
    }

    #[test]
    fn rejects_malformed_tokens() {
        let t = token();
        let good = t.encode();
        assert!(EnrollmentToken::parse(&good.replacen("upr_enr", "upr_agt", 1)).is_none());
        assert!(EnrollmentToken::parse(&format!("{good}.extra")).is_none());
        assert!(EnrollmentToken::parse(&good[..good.len() - 2]).is_none());
        assert!(EnrollmentToken::parse("upr_enr.not-a-uuid.s.00").is_none());
        assert!(EnrollmentToken::parse("").is_none());
        assert!(parse_auth_string("no-dot").is_none());
        assert!(parse_auth_string(&format!("{}.", t.id)).is_none());
        assert!(parse_auth_string(&format!("{}.bad secret", t.id)).is_none());
    }

    #[test]
    fn debug_hides_secret() {
        assert!(!format!("{:?}", token()).contains("abcDEF123"));
    }
}
